function beep(freq,duration,volume){try{audio=audio||new(window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.type='square';o.frequency.value=freq;g.gain.value=volume;o.connect(g);g.connect(audio.destination);o.start();g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.stop(audio.currentTime+duration)}catch(_){}}
function clearShot(a,b){const n=Math.ceil(dist(a,b)/24);for(let i=1;i<n;i++){let x=a.x+(b.x-a.x)*i/n,y=a.y+(b.y-a.y)*i/n;if(buildings.some(r=>x>r.x&&x<r.x+r.w&&y>r.y&&y<r.y+r.h))return false}return true}
function interact(){if(!running||paused||ended)return;let target=loot.find(l=>!l.taken&&dist(player,l)<49);if(target){target.taken=true;if(target.type==='core'){player.cores++;toast('DATA CORE SECURED');beep(680,.13,.04);if(player.cores===3)announce('OBJECTIVE COMPLETE // PROCEED TO UPLINK')}else{let roll=Math.random();if(roll<.4){player.reserve+=30;toast('AMMUNITION CACHE // +30 ROUNDS')}else if(roll<.72){player.hp=Math.min(100,player.hp+30);toast('MEDICAL SUPPLIES // VITALS RESTORED')}else{player.shield=Math.min(75,player.shield+30);toast('ARMOR CELL // SHIELD RECHARGED')}beep(520,.1,.035)}updateHud();return}
 if(dist(player,extract)<extract.r+23){if(!extract.active){extract.active=true;announce('UPLINK ACTIVATED // HOLD POSITION');toast('EXTRACTION SIGNAL TRANSMITTING')}else toast('HOLD E WITHIN THE UPLINK ZONE TO EXTRACT')}}
function damagePlayer(amount){if(player.invuln>0)return;player.invuln=.28;let remaining=amount;if(player.shield>0){let take=Math.min(player.shield,remaining);player.shield-=take;remaining-=take}player.hp=Math.max(0,player.hp-remaining);ui.damage.style.opacity='.76';setTimeout(()=>ui.damage.style.opacity='0',130);beep(95,.08,.04);if(player.hp<=0)endMission(false);updateHud()}
function update(dt){if(!running||paused||ended)return;elapsed+=dt;shotCooldown=Math.max(0,shotCooldown-dt);player.invuln=Math.max(0,player.invuln-dt);if(toastTimer>0&&(toastTimer-=dt)<=0)ui.toast.classList.remove('show');if(noticeTimer>0&&(noticeTimer-=dt)<=0)ui.notice.classList.remove('show');
 let dx=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0),dy=(keys.KeyS||keys.ArrowDown?1:0)-(keys.KeyW||keys.ArrowUp?1:0),moving=dx||dy,sprinting=(keys.ShiftLeft||keys.ShiftRight)&&moving&&player.stamina>0;let length=Math.hypot(dx,dy)||1;dx/=length;dy/=length;let speed=player.speed*(sprinting?1.52:1);if(sprinting)player.stamina=Math.max(0,player.stamina-25*dt);else player.stamina=Math.min(100,player.stamina+14*dt);
 let nx=player.x+dx*speed*dt,ny=player.y+dy*speed*dt;if(!blocked(nx,player.y,player.r))player.x=clamp(nx,player.r,WORLD.w-player.r);if(!blocked(player.x,ny,player.r))player.y=clamp(ny,player.r,WORLD.h-player.r);
 cam.x=clamp(player.x-innerWidth/2,0,WORLD.w-innerWidth);cam.y=clamp(player.y-innerHeight/2,0,WORLD.h-innerHeight);let aimX=mouse.x+cam.x,aimY=mouse.y+cam.y;player.angle=Math.atan2(aimY-player.y,aimX-player.x);if(mouse.down)fire();
 if(extract.active&&dist(player,extract)<extract.r&&keys.KeyE){extract.progress+=dt;if(extract.progress>=2.2)endMission(true)}else extract.progress=Math.max(0,extract.progress-dt*.6);
 let nearLoot=loot.find(l=>!l.taken&&dist(player,l)<55),nearExtract=dist(player,extract)<extract.r+30;ui.prompt.classList.toggle('visible',!!nearLoot||nearExtract);if(nearLoot)ui.promptText.textContent=nearLoot.type==='core'?'SECURE DATA CORE':'SCAVENGE CACHE';else if(nearExtract)ui.promptText.textContent=extract.active?'HOLD E TO EXTRACT':'ACTIVATE UPLINK';
 for(const e of enemies){if(e.hp<=0)continue;let d=dist(e,player);e.fire-=dt;e.stun=Math.max(0,e.stun-dt);if(d<510)e.alert=true;if(e.alert&&d>30){e.angle=Math.atan2(player.y-e.y,player.x-e.x);if(d>130){let speed=e.speed*(d<200?.4:1),ex=Math.cos(e.angle)*speed*dt,ey=Math.sin(e.angle)*speed*dt;let tx=e.x+ex,ty=e.y+ey;if(!blocked(tx,e.y,e.r))e.x=tx;else if(!blocked(e.x,ty,e.r))e.y=ty;else{let alt=e.angle+Math.PI/2;tx=e.x+Math.cos(alt)*speed*dt;ty=e.y+Math.sin(alt)*speed*dt;if(!blocked(tx,e.y,e.r))e.x=tx;if(!blocked(e.x,ty,e.r))e.y=ty}}
 if(d<425&&e.fire<=0&&clearShot(e,player)){e.fire=e.type==='heavy'?1.5:1.9;let a=Math.atan2(player.y-e.y,player.x-e.x)+rand(-.08,.08),v=e.type==='heavy'?320:390;bullets.push({x:e.x+Math.cos(a)*18,y:e.y+Math.sin(a)*18,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:1.3,hostile:true});if(d<270)beep(125,.04,.008)}}}
